 if(precision.includes('month'))extra.unshift('史料日期精确到月份；时间轴中的月内位置仅用于展示先后，不代表某日的确切位置。');
 const photo=photoFor(e);return `${photoHTML(e)}<div class="event-meta" style="color:${a.color}">${esc(getDate(e))}<span>${esc(e.phase==='prelude'?'序幕 · 前置历史':e.phase==='aftermath'?'长征后续':kindNames[e.kind]||'历史节点')}</span></div><h2>${esc(e.title)}</h2><p class="event-place"><span>⌖</span> ${esc(e.place)}</p><p class="event-body">${esc(e.summary)}</p>${extra.length?`<details class="event-details"><summary>考据与位置说明</summary><div class="event-extra">${extra.map(x=>`<p>${esc(x)}</p>`).join('')}</div></details>`:''}<div class="event-source"><span>据</span>${sources[0]?`<a href="${esc(sources[0].url)}" target="_blank" rel="noopener noreferrer">${esc(sources[0].title)} ↗</a>`:'<span>出处待核</span>'}${sources.length>1?`<button class="source-more" data-event-sources="${e.id}">+${sources.length-1}</button>`:''}</div>${photo?`<p class="photo-credit">图片：${esc(photo.author)} · <a href="${esc(photo.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(photo.license)} / 原图出处 ↗</a></p>`:''}`;
