  const e=sequence[session.index],next=sequence[session.index+1];
  if(session.phase==='reading'){
   if(!narration.enabled){session.phase='timed';session.elapsed=0;}
   else if(narration.isComplete(e.id)){session.phase='transition';session.elapsed=0;session.transitionStart=currentTime;}
   else{raf=requestAnimationFrame(frame);return;}
  }
  session.elapsed+=dt;
