  if(session.elapsed>=duration){if(!advance())return;raf=requestAnimationFrame(frame);return;}
  const raw=session.phase==='transition'?session.elapsed/duration:Math.max(0,Math.min(1,(session.elapsed/duration-.53)/.47)),p=raw*raw*(3-2*raw);
  playMotion={fromId:e.id,toId:next?.id,p};const from=session.phase==='transition'?(session.transitionStart??eventTime(e)):eventTime(e);
