 const labels=[['江西',115.4,27.5],['湖南',112,27.4],['贵州',107.1,26.2],['云南',101.7,24.9],['四川',103.9,30.4],['甘肃',103.6,36.6],['陕西',109.9,35.9],['河南',114.1,33.3],['湖北',113.1,30.8],['广西',108.9,24.1],['青海',99.4,36.9],['宁夏',106.1,37.6],['山西',112,37.2],['重庆',107.5,29.7]];
