function routeEvents(a){return a.events.filter(e=>e.route!==false&&e.phase!=='prelude'&&e.phase!=='aftermath');}
function linePath(points){return points.map((p,i)=>(i?'L':'M')+p.map(v=>v.toFixed(2)).join(',')).join('');}
function routeState(a){const es=routeEvents(a),points=es.map(e=>project(e.lon,e.lat)),fractions=es.slice(1).map(()=>0);if(!es.length||currentTime<eventTime(es[0]))return{path:'',position:null,fractions,reached:-1};const ts=es.map(eventTime),selectedIndex=selectedEvent?.armyId===a.id&&eventTime(selectedEvent)===currentTime?es.findIndex(e=>e.id===selectedEvent.id):-1;let pos=points[0],done=[pos],reached=0;for(let i=1;i<es.length;i++){let f;if(currentTime<ts[i])f=ts[i]===ts[i-1]?0:Math.max(0,Math.min(1,(currentTime-ts[i-1])/(ts[i]-ts[i-1])));else if(ts[i]===currentTime&&selectedIndex>=0&&i>selectedIndex)f=playMotion?.fromId===es[i-1].id&&playMotion?.toId===es[i].id?playMotion.p:0;else f=1;fractions[i-1]=f;if(f>=1){pos=points[i];done.push(pos);reached=i;}else{if(f>0){pos=[points[i-1][0]+(points[i][0]-points[i-1][0])*f,points[i-1][1]+(points[i][1]-points[i-1][1])*f];done.push(pos);}break;}}return{path:linePath(done),position:pos,fractions,reached};}
function armyPosition(a){return a?routeState(a).position:null;}
