function renderRoutes(){routeGroups.clear();nodeGroups.clear();$('#routes-layer').replaceChildren();$('#nodes-layer').replaceChildren();$('#markers-layer').replaceChildren();const visible=visibleArmies();for(const a of visible){const es=routeEvents(a);const g=svgEl('g',{class:'route-group','data-route':a.id},$('#routes-layer'));if(a.routeMode!=='fragments'&&a.category!=='special'){svgEl('path',{d:linePath(es.map(e=>project(e.lon,e.lat))),class:'route-ghost',stroke:a.color},g);const outline=svgEl('path',{class:'route-outline'},g);const main=svgEl('path',{class:'route-main',stroke:a.color,opacity:0},g);const history=svgEl('g',{class:'route-history',stroke:a.color},g);const segments=es.slice(1).map((e,i)=>svgEl('path',{class:'trail-segment',opacity:0},history));routeGroups.set(a.id,{outline,main,segments});}
 const nodeEvents=a.events.filter(e=>e.phase!=='aftermath');
 for(const e of nodeEvents){const[x,y]=project(e.lon,e.lat);const ng=svgEl('g',{class:'map-node',transform:`translate(${x},${y})`,'data-id':e.id,style:`--army:${a.color}`,tabindex:'0',role:'button','aria-label':getDate(e)+' '+e.title},$('#nodes-layer'));svgEl('title',{},ng).textContent=e.title+' · '+getDate(e);svgEl('circle',{r:13,class:'node-target'},ng);svgEl('circle',{r:12,stroke:a.color,class:'selected-ring',visibility:'hidden'},ng);svgEl('circle',{r:3.5,stroke:a.color,class:'node-dot'},ng);const label=svgEl('text',{x:10,y:-8,class:'node-label',visibility:'hidden'},ng);label.textContent=mapLabels[e.id]||shortPlace(e);nodeGroups.set(e.id,{node:ng,label,e,pt:[x,y]});}
 const marker=svgEl('g',{class:'unit-marker','data-marker':a.id},$('#markers-layer'));svgEl('circle',{r:22,fill:a.color,opacity:'.08'},marker);svgEl('circle',{r:13,stroke:a.color,class:'marker-ring'},marker);svgEl('circle',{r:7,fill:a.color,class:'marker-core'},marker);svgEl('circle',{r:2.3,fill:'#fff4dd',opacity:'.85'},marker);
 }
 if(selectedArmy==='all')for(const e of data.prologue||[]){if(e.armyId!=='vanguard')continue;const[x,y]=project(e.lon,e.lat);const ng=svgEl('g',{class:'map-node',transform:`translate(${x},${y})`,'data-id':e.id,role:'button',tabindex:0,'aria-label':e.title},$('#nodes-layer'));svgEl('circle',{r:14,class:'node-target'},ng);svgEl('circle',{r:5,stroke:'#8a7656',class:'node-dot'},ng);const label=svgEl('text',{x:12,y:-7,class:'node-label'},ng);label.textContent='北上抗日先遣队';nodeGroups.set(e.id,{node:ng,label,e,pt:[x,y]});}
 updateRouteProgress();}
function updateRouteProgress(){for(const a of visibleArmies()){const r=routeState(a),g=routeGroups.get(a.id),es=routeEvents(a);if(g){g.outline.setAttribute('d',r.path);g.outline.style.opacity='.34';g.main.setAttribute('d',r.path);const reached=r.reached;g.segments.forEach((segment,i)=>{const previous=es[i],next=es[i+1],fraction=r.fractions[i]||0;if(fraction===0){segment.setAttribute('d','');segment.style.opacity='0';return;}const p=project(previous.lon,previous.lat),q=project(next.lon,next.lat),tip=[p[0]+(q[0]-p[0])*fraction,p[1]+(q[1]-p[1])*fraction];segment.setAttribute('d',linePath([p,tip]));const age=Math.max(0,reached-i-1);segment.style.opacity=String(Math.max(.28,.96*Math.exp(-age*.23)));});}const m=$(`[data-marker="${a.id}"]`);if(m){m.setAttribute('visibility',r.position&&a.category!=='special'?'visible':'hidden');if(r.position)m.setAttribute('transform',`translate(${r.position[0]},${r.position[1]})`);}}for(const {node,e}of nodeGroups.values()){const future=eventTime(e)>currentTime;node.style.opacity=future?'.15':'.85';node.setAttribute('data-future',future);}renderSelectedNode();resizeMarkers();}
function mapReservations(){
 const stage=$('#map-stage').getBoundingClientRect();
 return ['.map-title','.sidebar','.time-console','.map-top-actions','.map-toolbar','.compass'].map(selector=>$(selector)).filter(el=>el&&getComputedStyle(el).display!=='none').map(el=>{const r=el.getBoundingClientRect();return{x:r.left-stage.left-5,y:r.top-stage.top-5,w:r.width+10,h:r.height+10};});
}
function renderSelectedNode(){
 const stage=$('#map-stage'),height=stage.clientHeight,width=stage.clientWidth;if(!height)return;
 const selected=selectedEvent?.id,k=camera.height/height;
 const occupied=[...(geographyLayer?.update({camera,width,height,selectedId:selected,reserved:mapReservations(),riversVisible:$('#layer-rivers')?.checked!==false,landmarksVisible:$('#layer-landmarks')?.checked!==false})||[])];
 const persistent=new Set($('#layer-landmarks')?.checked===false?[]:geographyData?.landmarks.flatMap(p=>p.eventIds||[])||[]);
 const sorted=[...nodeGroups.values()].sort((a,b)=>Number(b.e.id===selected)-Number(a.e.id===selected));
 for(const{node,label,e,pt}of sorted){
  node.setAttribute('transform',`translate(${pt[0]},${pt[1]}) scale(${k})`);const isSelected=e.id===selected;node.classList.toggle('selected',isSelected);node.querySelector('.selected-ring')?.setAttribute('visibility',isSelected?'visible':'hidden');
  const sx=(pt[0]-camera.cx)/k+width/2,sy=(pt[1]-camera.cy)/k+height/2;
  const rect={x:sx+9,y:sy-19,w:label.textContent.length*12,h:17};
  const collision=occupied.some(p=>rect.x<p.x+p.w+3&&rect.x+rect.w+3>p.x&&rect.y<p.y+p.h+3&&rect.y+rect.h+3>p.y);
  const wanted=!persistent.has(e.id)&&(isSelected||(camera.height<500&&eventTime(e)<=currentTime));
  label.setAttribute('visibility',wanted&&(!collision||isSelected)?'visible':'hidden');
  label.removeAttribute('transform');label.setAttribute('x',9);label.setAttribute('y',-9);
  if(wanted&&!collision)occupied.push(rect);
 }
}
