function updateCamera(){
 const box=$('#map-stage').getBoundingClientRect();if(!box.width||!box.height)return;
 const aspect=box.width/box.height,w=camera.height*aspect,k=camera.height/box.height;
 if(k!==lastMapTextScale){lastMapTextScale=k;$$('.province-label').forEach(el=>{el.style.fontSize=(el.classList.contains('small')?18:23)*k+'px';el.style.letterSpacing=4*k+'px';});$$('.mountain-label').forEach(el=>{el.style.fontSize=12*k+'px';el.style.letterSpacing=2*k+'px';});}
 $('#map-svg').setAttribute('viewBox',`${camera.cx-w/2} ${camera.cy-camera.height/2} ${w} ${camera.height}`);
 renderSelectedNode();resizeMarkers();
}
function fitMap(){
 const pts=visibleArmies().flatMap(routeEvents).map(e=>project(e.lon,e.lat));if(!pts.length)return;
 const stage=$('#map-stage'),w=stage.clientWidth,h=stage.clientHeight,mobile=matchMedia('(max-width:760px)').matches;
 const padding=mobile?{left:22,right:22,top:150,bottom:140}:{left:170,right:62,top:160,bottom:165};
 const safeW=Math.max(w*.48,w-padding.left-padding.right),safeH=Math.max(h*.28,h-padding.top-padding.bottom);
 const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
 const scale=Math.max(.01,Math.min(safeW/Math.max(210,maxX-minX),safeH/Math.max(250,maxY-minY))*.96);
 const safeCX=padding.left+safeW/2,safeCY=padding.top+safeH/2;
 camera={cx:(minX+maxX)/2-(safeCX-w/2)/scale,cy:(minY+maxY)/2-(safeCY-h/2)/scale,height:h/scale};updateCamera();
}
