function renderChronology(){let parallel=$('#parallel-timeline');if(!parallel){parallel=document.createElement('div');parallel.id='parallel-timeline';$('#chrono-filters').before(parallel);}parallel.innerHTML='<p class="eyebrow">四支部队 · 长征起止对照</p>'+mainArmies().map(a=>`<button class="parallel-row" data-chrono-army="${a.id}" style="--army:${a.color}"><span>${esc(a.id==='second'?'红二、六军团':a.shortName)}</span><span class="parallel-track"><i style="left:${100*(time(a.start)-startTime)/(endTime-startTime)}%;width:${100*(time(a.end)-time(a.start))/(endTime-startTime)}%"><b>${esc(a.period)}</b></i></span></button>`).join('');const list=events.filter(e=>e.armyId!=='regiment'&&(chronoArmy==='all'||chronoArmy==='prologue'?chronoArmy==='all'||e.phase==='prelude'||(data.prologue||[]).some(p=>p.id===e.id):e.armyId===chronoArmy)).sort((a,b)=>eventTime(a)-eventTime(b));const grouped=Map.groupBy(list,e=>(e.date||'').slice(0,7));$('#chronology-list').innerHTML=[...grouped].map(([month,es])=>`<section class="chrono-month"><h2>${esc(month.replace('-','.'))}</h2><div class="chrono-events">${es.map(e=>{const a=getArmy(e.armyId);return `<button class="chrono-event" data-event="${e.id}" style="--army:${a.color}"><small>${esc(getDate(e))} / ${esc(eventArmyName(e))}${e.phase==='prelude'?' · 序幕':''}${e.phase==='aftermath'?' · 后续':''}</small><h3>${esc(e.title)} <span>↗</span></h3><p>${esc(e.summary)}</p><span>⌖ ${esc(e.place)}</span></button>`;}).join('')}</div></section>`).join('');$('#chrono-filters').innerHTML=[{id:'all',shortName:'全部对照'},{id:'prologue',shortName:'序幕 · 先遣行动'},...mainArmies()].map(a=>`<button class="filter-chip ${chronoArmy===a.id?'active':''}" data-chrono-army="${a.id}">${esc(a.shortName)}</button>`).join('');}
function researchNotes(){return[
 ['四支部队，不同起止','中央红军：1934年10月至1935年10月；红二十五军：1934年11月至1935年9月；红四方面军：1935年3月至1936年10月；红二、六军团：1935年11月至1936年10月，途中组成红二方面军。1934年7月北上抗日先遣队与8月红六军团西征，作为序幕单列。'],
 ['会师，是一个过程','达维的先头部队会合与主力到懋功不同。1936年7月2日甘孜庆祝会师、7月5日组成红二方面军分别列示。1936年10月9日会宁、10月22日将台堡是两处主要会师节点；各部先头、总部和后续并非同刻抵达。'],
 ['路线，有明确的精度边界','线条连接现代地名的概略坐标，只表达已知重要节点的空间先后，不能用于复原每日行军距离、速度或具体山路。虚线为尚未到达的后续节点；播放采用相邻事件约等时的节奏，日期仍为真实史实时间；移动位置仅作两节点间插值。旧路线逐渐褪淡并保留，不用来表示兵力损失。月级事件的月内排列仅为动画叙事，显示日期仍保持月级。'],
 ['番号、分兵与历史范围','1935年的左、右路军是混编行军序列，不能直接等同于一、四方面军。红四方面军1936年北上分纵队；红二、六军团也有支路。方面军路线呈现主要活动地区，不表示每个团同行。吴起以后的红一方面军接应、红二十五军改编另列为后续，西路军另属后续历史。'],
 ['湘江的代价，怎样表述','“出发时8.6万余人，湘江战役后3万余人”是两个时点的兵力对比，包含长征初期以来的战斗、掉队等累计减员，不能写成湘江一役阵亡5.6万人。整体战役与关键渡江作战的起日有不同叙述，事件卡保留资料口径。'],
 ['红四团专题：片段而非全轨迹','专题仅使用明确提及红一军团二师四团的史料。乌江、泸定桥、夹金山、腊子口等团级节点单独核对；安顺场强渡大渡河属于红一师一团，不计入红四团。专题不把方面军行程复制为团级位置。'],
 ['日期异文与地名沿革','北上抗日先遣队出发，官方资料有1934年7月6日、7日两种叙述，界面采用“7月上旬”。红四方面军长征起点采用3月强渡嘉陵江的常用口径。百丈关采用11月19—25日主要激战时段，并保留更宽战事口径。懋功今小金，大定今大方，中甸今香格里拉；今属宁夏的将台堡当时属甘肃。'],
 ['覆盖范围与继续细化','本版覆盖四支主要部队的重要战役、会议、战略转向、会师和沿革，附红四团专题与先遣行动。它不是全部师团、每次战斗和逐日军史的穷尽记录。对未精确到日、分路不一、资料叙述不同的节点，保留说明而不补造细节。']];}
function renderSources(){
 const geographySection=document.createElement('details');geographySection.className='geography-sources';
 geographySection.innerHTML=`<summary>关键地理与常驻地名 · ${geographyData.landmarks.length}处地标 / ${geographyData.sources.length}条参考</summary><p>重要地名不随播放日期或所选部队隐藏；密集地名放大展开。地点采用现代概略锚点，不是旧址精密测绘。四渡赤水按渡口群关联事件，不把同一次渡河缩成唯一渡口。河线与点位来自不同尺度资料，可能有小幅偏差。</p>${geographyData.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a> · ${esc(s.publisher||'')}</p>`).join('')}<p>赤水河：<a href="https://www.openstreetmap.org/relation/19390444" target="_blank" rel="noopener noreferrer">OSM关系19390444</a>，保留原始河线；© OpenStreetMap contributors，<a href="https://opendatacommons.org/licenses/odbl/1-0/" target="_blank" rel="noopener noreferrer">ODbL 1.0</a>。乌江、湘江：Natural Earth 1:10,000,000制图中心线；其他主河：1:50,000,000。均为现代地理参考。</p>`;
 $('.geo-credit').before(geographySection);
 const historyEvents=events.filter(e=>e.armyId!=='regiment');$('#research-summary').innerHTML=`<div class="research-stats"><div><strong>04</strong><span>主要长征部队</span></div><div><strong>${historyEvents.length}</strong><span>主线与前史历史节点</span></div><div><strong>${data.sources.length}</strong><span>可溯源公开资料</span></div><div><strong>08</strong><span>红四团专题片段</span></div></div><div class="research-grid">${researchNotes().map(([title,body],i)=>`<article class="research-note"><span class="note-no">0${i+1}</span><h2>${title}</h2><p>${body}</p></article>`).join('')}</div><details class="dataset-notes"><summary>展开各部队原始考据备注</summary>${armies.map(a=>`<h3>${esc(a.name)}</h3>${(Array.isArray(a.notes)?a.notes:[a.notes]).filter(Boolean).map(n=>`<p>${esc(typeof n==='string'?n:JSON.stringify(n))}</p>`).join('')}`).join('')}</details>`;
 const photoSection=document.createElement('div');photoSection.id='image-sources';photoSection.innerHTML='<h2 class="photo-heading">影像来源与授权</h2><p class="photo-intro">以下为有明确授权的旧址或地理环境当代照片，均不是1930年代战地原照。窗口显示按比例裁切，并作轻微低饱和色调处理；原始图片文件未改色。</p>'+photoData.images.map(p=>`<article class="photo-source-row"><img src="${esc(p.file)}" alt="${esc(p.caption)}" loading="lazy"><div><h3>${esc(p.title)}</h3><p>${esc(p.caption)}</p><p>${esc(p.author)} · <a href="${esc(p.licenseUrl||p.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.license)}</a> · <a href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">原图出处 ↗</a></p></div></article>`).join('');$('.geo-credit').before(photoSection);$('#source-count').textContent=`${data.sources.length} 条 · 每个历史事件均关联出处`;
 $('#source-list').innerHTML=data.sources.map((s,i)=>{const ids=new Set([s.id,...s.aliases||[]]);const used=events.filter(e=>e.sources?.some(id=>ids.has(id)));return `<article class="source-row"><span class="source-number">${String(i+1).padStart(2,'0')}</span><div><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p>用于 ${used.length} 个历史节点${s.type?' · '+esc(s.type):''}</p></div><small>${esc(s.publisher||new URL(s.url).hostname)}</small></article>`;}).join('');}
function renderSearch(query=''){const q=query.trim().toLowerCase();const found=events.filter(e=>!q||[e.title,e.place,e.summary,getArmy(e.armyId).name,getDate(e)].join(' ').toLowerCase().includes(q)).sort((a,b)=>eventTime(a)-eventTime(b));$('#event-results').innerHTML=found.length?found.map(e=>{const a=getArmy(e.armyId);return `<button class="search-result" data-event="${e.id}" style="--army:${a.color}"><span>${esc(getDate(e))}</span><div><strong>${esc(e.title)}</strong><small>${esc(eventArmyName(e))} · ${esc(e.place)}</small></div></button>`;}).join(''):'<p class="no-results">没有找到匹配节点。试试地名、部队名或“会师”。</p>';}
function openSearch(){pause();$('#events-dialog').showModal();$('#event-search').value='';renderSearch();setTimeout(()=>$('#event-search').focus(),100);}
function showEventSources(id){const e=eventById.get(id);if(!e)return;pause();$('#events-dialog').showModal();$('#event-search').value=e.title;$('#event-results').innerHTML=`<p class="source-dialog-title">${esc(e.title)} · 史料出处</p>${eventSources(e).map(s=>`<article class="dialog-source"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p>${esc(s.publisher)}</p></article>`).join('')}`;}
function bindUI(){$('.brand').onclick=e=>{e.preventDefault();selectView('map');};$('#nav-reveal').onclick=()=>{const open=$('.masthead').classList.toggle('pinned-open');$('#nav-reveal').setAttribute('aria-expanded',String(open));};document.addEventListener('click',ev=>{const b=ev.target.closest('.nav-btn[data-view]');if(b?.dataset.view)selectView(b.dataset.view);const army=ev.target.closest('[data-army]');if(army)selectArmy(army.dataset.army);const event=ev.target.closest('[data-event]');if(event)jumpToEvent(event.dataset.event);const filter=ev.target.closest('[data-chrono-army]');if(filter){chronoArmy=filter.dataset.chronoArmy;renderChronology();}const src=ev.target.closest('[data-event-sources]');if(src)showEventSources(src.dataset.eventSources);});$('#play-btn').onclick=play;$('#prev-event').onclick=()=>eventStep(-1);$('#next-event').onclick=()=>eventStep(1);$('#speed-btn').onclick=()=>{const speeds=[1,1.25,1.5,2];speed=speeds[(speeds.indexOf(speed)+1)%speeds.length];$('#speed-btn').textContent=speed+'×';narration.setRate(speed);};$('#time-slider').addEventListener('input',e=>{pause();resetNarration();playbackSession=null;playMotion=null;changeTime(startTime+(endTime-startTime)*e.target.value/1000);renderRoutes();});$('#zoom-in').onclick=()=>zoom(.75);$('#zoom-out').onclick=()=>zoom(1.3);$('#reset-map').onclick=showOverview;$('#follow-toggle').onclick=toggleFollow;$('#follow-view').onclick=toggleFollow;$('#overview-view').onclick=showOverview;$('#layers-toggle').onclick=()=>{const p=$('#layer-panel');p.hidden=!p.hidden;$('#layers-toggle').setAttribute('aria-expanded',!p.hidden);};for(const [id,layer]of[['admin','province'],['rivers','river'],['terrain','terrain'],['landmarks','landmarks']])$('#layer-'+id).onchange=e=>{$('#'+layer+'-layer').style.display=e.target.checked?'':'none';if(id==='admin')$('#province-labels').style.display=e.target.checked?'':'none';if(id==='rivers')$$('.geo-river').forEach(x=>x.style.display=e.target.checked?'':'none');renderSelectedNode();};$('#map-method').onclick=()=>{selectView('sources');window.scrollTo(0,0);};$('#search-toggle').onclick=openSearch;$('#open-stories').onclick=openSearch;$('#event-search').oninput=e=>renderSearch(e.target.value);$('.close-dialog').onclick=()=>$('#events-dialog').close();$('#events-dialog').onclick=e=>{if(e.target===$('#events-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
const svg=$('#map-svg');svg.addEventListener('click',e=>{const node=e.target.closest('.map-node');if(node&&!dragged&&!pointer){};});svg.addEventListener('keydown',e=>{const landmark=e.target.closest('[data-landmark]');if(landmark&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.stopPropagation();showLandmark(landmark.dataset.landmark);return;}const node=e.target.closest('.map-node');if(node&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.stopPropagation();jumpToEvent(node.dataset.id,{focus:false});}});svg.addEventListener('pointerdown',e=>{if(e.button!==0||pointer)return;pointer={id:e.pointerId,x:e.clientX,y:e.clientY,cx:camera.cx,cy:camera.cy,nodeId:e.target.closest('.map-node')?.dataset.id,landmarkId:e.target.closest('[data-landmark]')?.dataset.landmark};dragged=false;svg.setPointerCapture(e.pointerId);});svg.addEventListener('pointermove',e=>{if(pointer&&e.pointerId!==pointer.id)return;if(!pointer){const landmark=e.target.closest('[data-landmark]');if(landmark){const tooltip=$('#map-tooltip');tooltip.hidden=false;tooltip.textContent=landmark.querySelector('title').textContent;const r=$('#map-stage').getBoundingClientRect();tooltip.style.left=Math.max(8,Math.min(e.clientX-r.left+15,r.width-230))+'px';tooltip.style.top=Math.min(e.clientY-r.top+17,r.height-85)+'px';return;}const node=e.target.closest('.map-node');const tooltip=$('#map-tooltip');if(node){const ev=eventById.get(node.dataset.id);if(ev){tooltip.hidden=false;tooltip.innerHTML=`<small>${esc(getDate(ev))}</small>${esc(ev.title)}`;const r=$('#map-stage').getBoundingClientRect();tooltip.style.left=Math.min(e.clientX-r.left+15,r.width-230)+'px';tooltip.style.top=e.clientY-r.top+17+'px';}}else tooltip.hidden=true;return;}const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.abs(dx)+Math.abs(dy)>5){dragged=true;svg.classList.add('dragging');follow=false;updateFollowUI();renderTime();$('#map-tooltip').hidden=true;}if(dragged){const k=camera.height/$('#map-stage').clientHeight;camera.cx=pointer.cx-dx*k;camera.cy=pointer.cy-dy*k;updateCamera();}});const release=e=>{if(pointer&&e.pointerId!==pointer.id)return;if(!dragged){if(pointer?.landmarkId)showLandmark(pointer.landmarkId);else if(pointer?.nodeId)jumpToEvent(pointer.nodeId,{focus:false});}pointer=null;svg.classList.remove('dragging');setTimeout(()=>dragged=false,10);};svg.addEventListener('pointerup',release);svg.addEventListener('pointercancel',()=>{pointer=null;dragged=false;svg.classList.remove('dragging');});svg.addEventListener('pointerleave',()=>$('#map-tooltip').hidden=true);svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.07:.93,svgPoint(e));},{passive:false});new ResizeObserver(()=>{if(activeView==='map')updateCamera();}).observe($('#map-stage'));document.addEventListener('keydown',e=>{if(e.defaultPrevented||e.target.matches('input,button,summary,a,select,textarea')||$('#events-dialog').open)return;if(e.code==='Space'&&activeView==='map'){e.preventDefault();play();}if(e.key==='ArrowRight'&&activeView==='map')eventStep(1);if(e.key==='ArrowLeft'&&activeView==='map')eventStep(-1);});}
async function loadMapData(urls){
 const results=new Array(urls.length);let cursor=0;
 const load=async url=>{let failure;for(let attempt=0;attempt<3;attempt++){try{const response=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error(url+' '+response.status);return await response.json();}catch(error){failure=error;if(attempt<2)await new Promise(resolve=>setTimeout(resolve,250*(attempt+1)));}}throw failure;};
 await Promise.all(Array.from({length:Math.min(3,urls.length)},async()=>{while(cursor<urls.length){const index=cursor++;results[index]=await load(urls[index]);}}));
 return results;
}
async function init(){try{[data,provinceData,riverData,photoData,geographyData,supplementalRivers,staticNarrationManifest]=await loadMapData(['data.json','assets/china-provinces.geojson','assets/rivers.geojson','photos.json','geography.json','assets/long-march-rivers.geojson',...(staticNarrationURL?[staticNarrationURL]:[])]);narration=new NarrationController({enabled:true,voice:'yunxi',...narrationPrefs(),...(staticNarrationManifest?{staticManifest:staticNarrationManifest,staticBaseURL:new URL(staticNarrationURL,document.baseURI).href}:{})});armies=data.armies;sourceById=new Map();for(const s of data.sources)for(const id of [s.id,...s.aliases||[]])sourceById.set(id,s);for(const a of armies)for(const s of a.sources||[])if(!sourceById.has(s.id))sourceById.set(s.id,s);const unique=new Map([...armies.flatMap(a=>a.events.map(e=>({...e,armyId:a.id}))),...data.prologue||[]].map(e=>[e.id,e]));events=[...unique.values()];eventById=new Map(events.map(e=>[e.id,e]));if(data.meta?.timeline){startTime=time(data.meta.timeline.start||data.meta.timeline.min);endTime=time(data.meta.timeline.end||data.meta.timeline.max);}currentTime=endTime;selectedEvent=events.find(e=>e.id==='second-19')||latestEvent();mobileStory=document.createElement('div');mobileStory.className='mobile-story';mobileStory.innerHTML='<article class="event-card"></article><div class="mobile-toolbar"><button class="text-btn" data-army="all">四支部队对照 ↗</button><button class="read-more mobile-search">浏览历史节点 ↗</button></div><button class="special-trace" data-army="regiment"><span>专题</span> 跟随红四团 ↗</button>';$('#map-view').append(mobileStory);$('.mobile-search').onclick=openSearch;
 const chapters=document.createElement('div');chapters.className='map-chapters';chapters.innerHTML='<button data-chapter="prologue">序幕 <span>1934.07</span></button><button data-chapter="departure">出发 <span>1934.10</span></button><button data-chapter="turn">转折 <span>1935.01</span></button><button data-chapter="reunion">会师 <span>1936.10</span></button><button data-chapter="chishui" class="chishui-entry">四渡赤水 ↗</button>';$('.map-title').append(chapters);chapters.onclick=e=>{const b=e.target.closest('[data-chapter]');if(!b)return;const c=b.dataset.chapter;pause();if(c==='chishui'){focusChishui();}else if(c==='prologue'){chronoArmy='prologue';renderChronology();selectView('chronology');window.scrollTo(0,0);}else if(c==='departure')jumpToEvent('central-yudu');else if(c==='turn')jumpToEvent('central-zunyi-meeting');else{resetNarration();playbackSession=null;playMotion=null;selectedArmy='all';follow=false;updateFollowUI();currentTime=endTime;selectedEvent=eventById.get('second-19');renderArmyList();renderTime();renderRoutes();fitMap();renderCard();}};
 const floating=document.createElement('aside');floating.className='floating-event';floating.setAttribute('aria-label','重点事件浮窗');const heading=$('.story-heading');heading.querySelector('.eyebrow').textContent='沿途 · 历史档案';const controls=document.createElement('div');controls.className='window-controls';controls.append($('#search-toggle'));const collapse=document.createElement('button');collapse.className='icon-btn';collapse.id='event-collapse';collapse.setAttribute('aria-label','收起事件浮窗');collapse.textContent='−';collapse.onclick=()=>{const off=floating.classList.toggle('collapsed');collapse.textContent=off?'＋':'−';collapse.setAttribute('aria-label',off?'展开事件浮窗':'收起事件浮窗');};controls.append(collapse);heading.append(controls);floating.append(heading,$('#event-card'),$('#open-stories'));const specialist=document.createElement('button');specialist.className='regiment-entry';specialist.dataset.army='regiment';specialist.textContent='专题追踪 · 红四团 ↗';heading.after(specialist);const quick=document.createElement('div');quick.className='window-quick-nav';quick.innerHTML='<button id="float-prev">← 上一事件</button><button id="float-next">下一事件 →</button>';quick.querySelector('#float-prev').onclick=()=>eventStep(-1);quick.querySelector('#float-next').onclick=()=>eventStep(1);floating.append(quick);$('#map-view').append(floating);$('.console-foot>span:last-child').textContent='事件等时播放 · 旧路线褪淡保留';const clock=document.createElement('span');clock.className='event-clock';clock.innerHTML='<span></span> 每节点约4秒';$('.play-controls').before(clock);renderArmyList();renderBaseMap();renderChronology();renderSources();renderTime();renderRoutes();renderCard();fitMap();bindUI();updateFollowUI();initNarrationUI();$('#load-state').hidden=true;selectView(['chronology','sources'].includes(location.hash.slice(1))?location.hash.slice(1):'map');
 const tickDates=['1934-07-01','1934-10-01','1935-01-01','1935-04-01','1935-07-01','1935-10-01','1936-01-01','1936-04-01','1936-07-01','1936-10-22'];$('.timeline-ticks').innerHTML=tickDates.map(d=>`<span style="left:${100*(time(d)-startTime)/(endTime-startTime)}%">${d.slice(0,7).replace('-','.')}</span>`).join('');const eras=['1934-10-17','1935-01-15','1935-06-12','1935-10-19','1936-07-02','1936-10-09'];$('#timeline-eras').innerHTML=eras.map(d=>`<i style="left:${100*(time(d)-startTime)/(endTime-startTime)}%"></i>`).join('');
 window.atlas={get state(){return{selectedArmy,currentTime:dateText(currentTime),selectedEvent:selectedEvent?.id,playing,follow}},get data(){return data},jumpToEvent,selectArmy,changeTime};
 }catch(error){console.error(error);$('#load-state').textContent='地图暂未展开。请刷新重试。';}}
